import {money,quote,rates,schedule,today,escapeHTML as e,loanBook,addDays} from '/domain.js';
const $=(s,root=document)=>root.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const main=$('#main');
let appSaving=false;
let services=[],help=[],filter='All',route=location.pathname,calcWeeks=2,appStep=0,appData={},appFiles={},records=[],currentRecord=null,toastTimer;
const pageTitles={'/':'Lending & IT Consulting','/lending':'Avesta Lending','/it':'Avesta Consulting','/calculator':'Loan Calculator','/how-it-works':'How It Works','/currency':'Currency Converter','/apply':'Loan Application','/about':'About Avesta','/contact':'Contact','/portal':'Private Portal','/privacy':'Privacy','/terms':'Terms','/complaints':'Complaints'};
const lendingPaths=['/lending','/how-it-works','/calculator','/currency','/apply'];
const icon=(name)=>{const paths={clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="M5 12l4 4L19 6"/>',phone:'<path d="M7 3H4v5c0 7 5 12 12 12h5v-3l-5-2-2 2c-3-1-6-4-7-7l2-2z"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',pin:'<path d="M20 10c0 6-8 11-8 11S4 16 4 10a8 8 0 0 1 16 0z"/><circle cx="12" cy="10" r="2.5"/>',shield:'<path d="m12 3 8 3v5c0 5-4 9-8 10-4-1-8-5-8-10V6z"/><path d="m8 12 3 3 5-6"/>',file:'<path d="M14 3H5v18h14V8zM14 3v5h5M8 12h8M8 16h6"/>',tech:'<rect x="3" y="3" width="18" height="13" rx="2"/><path d="M8 21h8M12 16v5"/>'};return `<span class="icon" aria-hidden="true"><svg viewBox="0 0 24 24">${paths[name]||paths.check}</svg></span>`;};
const head=(eyebrow,title,subtitle)=>`<section class="page-head"><div class="wrap"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div></section>`;
const cta=(title,text,label='/apply',button='Apply for a loan')=>`<div class="cta"><div><h2>${title}</h2><p>${text}</p></div><a class="button" href="${label}">${button}</a></div>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function localLink(url){return url.origin===location.origin&&url.pathname!=='/signout-with-chatgpt'&& !url.pathname.startsWith('/api/');}
function navigate(path,push=true){if(appSaving){toast('Please wait while the application is saved.');return;}if(route==='/apply'&&Object.keys(appData).length&&!appData.submitted&&path!='/apply'&&!confirm('Leave your application? Your progress will remain available until this page is closed.'))return;if(push)history.pushState({},'',path);route=new URL(path,location.origin).pathname;render();window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});}
document.addEventListener('click',ev=>{if(ev.defaultPrevented)return;const a=ev.target.closest('a');if(!a||ev.ctrlKey||ev.metaKey||ev.shiftKey||ev.altKey||a.target||a.hasAttribute('download'))return;const url=new URL(a.href);if(localLink(url)&&pageTitles[url.pathname]){ev.preventDefault();if(url.pathname===route&&url.hash){document.getElementById(url.hash.slice(1))?.scrollIntoView({behavior:'smooth'});return;}navigate(url.pathname+url.search+url.hash);}});
window.addEventListener('popstate',()=>{route=location.pathname;render();});
$('.menu-toggle').addEventListener('click',()=>{const open=$('.menu-toggle').getAttribute('aria-expanded')!=='true';$('.menu-toggle').setAttribute('aria-expanded',String(open));$('.menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation');$('#mobile-nav').hidden=!open;});
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){$('#mobile-nav').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');}});
$('.dialog-close').addEventListener('click',()=>$('#dialog').close());
$('#dialog').addEventListener('click',ev=>{if(ev.target===$('#dialog'))$('#dialog').close();});
$('#year').textContent=new Date().getFullYear();
function shell(){
 document.title=(pageTitles[route]||'Page not found')+' · Avesta Enterprises';
 $$('.desktop-nav a').forEach(a=>{const active=a.getAttribute('href')===route||(a.dataset.nav==='lending'&&lendingPaths.includes(route));a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 $('#mobile-nav').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false');
 $('#subnav').innerHTML=lendingPaths.includes(route)?`<nav class="subnav" aria-label="Lending navigation"><div class="wrap">${[['/lending','Overview'],['/how-it-works','How it works'],['/calculator','Loan calculator'],['/currency','Currency converter'],['/apply','Apply now']].map(([p,label])=>`<a href="${p}" class="${route===p?'active':''}" ${route===p?'aria-current="page"':''}>${label}</a>`).join('')}</div></nav>`:'';
}
function home(){return `
<section class="hero"><div class="wrap"><div class="hero-grid">
 <div class="hero-copy"><div class="eyebrow">Ndola roots. Zambia-wide reach.</div><h1>A little support.<br><em>A lot of possibility.</em></h1><p>Finance when you need it. Technology that keeps you moving. Avesta brings straightforward lending and practical IT support to people and businesses across Zambia.</p><div class="actions"><a class="button secondary" href="/lending">Explore our loans</a><a class="link" href="/it">Find IT support</a></div><p class="hero-note"><span></span> One company. Two ways to help you get going.</p></div>
 <div><a class="choice-card" href="/lending"><div class="choice-top"><span>Avesta Lending</span><span class="card-number">01</span></div><h2>Your next step, funded.</h2><p>Short-term finance with the amount, interest and repayments clearly explained.</p><div class="choice-bottom"><span>1–4 week terms · ZMW</span><strong>Explore lending</strong></div></a><a class="choice-card tech" href="/it"><div class="choice-top"><span>Avesta Consulting</span><span class="card-number">02</span></div><h2>Get back to working.</h2><p>Repairs, networks, websites and security. Practical support for the technology you rely on.</p><div class="choice-bottom"><span>11 services · Remote & on-site</span><strong>Explore IT services</strong></div></a></div>
</div><div class="trust-row"><div><strong>Clear</strong> Terms and costs up front</div><div><strong>Local</strong> Head office in Kansenshi, Ndola</div><div><strong>Flexible</strong> Support that fits your needs</div></div></div></section>
<section class="section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">Start with what you need</div><h2>Good decisions start with clarity.</h2></div><p>Compare your options, ask a question, or take the first step. We’re here to help.</p></div><div class="card-grid"><article class="card">${icon('file')}<h3>Understand your loan</h3><p>See the process, documents and published terms before you apply.</p><a class="link" href="/how-it-works">How lending works</a></article><article class="card">${icon('clock')}<h3>Plan your repayments</h3><p>Choose an amount and term to see the full cost and repayment schedule.</p><a class="link" href="/calculator">Use the calculator</a></article><article class="card">${icon('tech')}<h3>Solve a technology problem</h3><p>Find the right service or try our practical IT help guide.</p><a class="link" href="/it#help">Find IT help</a></article></div></div></section>
<section class="section soft"><div class="wrap">${cta('Let’s work out the next step.','Speak to the team by phone, WhatsApp or email, or visit our Ndola office.','/contact','Get in touch')}</div></section>`;}
function quoteControls(prefix,compact=false){
 const q=quote(1000,calcWeeks);
 return `<div class="quote-card ${compact?'compact':''}"><div class="eyebrow">Know the cost before you apply</div><h2>${compact?'A quick loan estimate':'Build your repayment plan'}</h2><label class="field" for="${prefix}-amount">Loan amount<div class="input-prefix"><span>ZMW</span><input id="${prefix}-amount" type="number" inputmode="decimal" min="1" max="1000000" step="0.01" value="1000"></div></label><div class="field"><span id="${prefix}-term-label">Loan term</span></div><div class="term-picker" role="group" aria-labelledby="${prefix}-term-label">${Object.keys(rates).map(w=>`<button type="button" data-week="${w}" class="${Number(w)===calcWeeks?'active':''}" aria-pressed="${Number(w)===calcWeeks}">${w} ${Number(w)===1?'week':'weeks'}<span>${rates[w]}% flat</span></button>`).join('')}</div>${compact?'':`<label class="field" for="${prefix}-frequency">Repayment schedule<select id="${prefix}-frequency"><option>Weekly</option><option>Bi-weekly</option><option>Monthly</option><option selected>Lump sum</option></select></label><label class="field" for="${prefix}-start">Estimated disbursement date<input id="${prefix}-start" type="date" value="${today()}"></label>`}<div id="${prefix}-error" role="alert"></div><div id="${prefix}-result" aria-live="polite"><div class="quote-total"><span>Total to repay</span><strong>${money(q.total/100)}</strong></div><div class="breakdown"><div>Principal<strong>${money(q.principal/100)}</strong></div><div>Interest · ${q.rate}%<strong>${money(q.interest/100)}</strong></div></div></div><div class="actions"><a class="button secondary" id="${prefix}-apply" href="/apply?amount=1000&weeks=${calcWeeks}">Continue to application</a></div><p class="updated">An estimate, subject to assessment and written agreement.</p></div>`;
}
function bindQuote(prefix,compact=false){
 const box=$('#'+prefix+'-amount').closest('.quote-card');
 const update=()=>{
  try{const amount=Number($('#'+prefix+'-amount').value),freq=compact?'Lump sum':$('#'+prefix+'-frequency').value;const q=quote(amount,calcWeeks,freq);
   $('#'+prefix+'-result').innerHTML=`<div class="quote-total"><span>Total to repay</span><strong>${money(q.total/100)}</strong></div><div class="breakdown"><div>Principal<strong>${money(q.principal/100)}</strong></div><div>Interest · ${q.rate}%<strong>${money(q.interest/100)}</strong></div></div>${compact?'':`<p class="updated">${q.count} ${q.count===1?'payment':'payments'} · ${money(q.instalments[0]/100)}${q.instalments.some(v=>v!==q.instalments[0])?' (final amounts adjusted to the ngwee)':''}</p>`}`;
   $('#'+prefix+'-apply').href='/apply?amount='+amount+'&weeks='+calcWeeks+'&frequency='+encodeURIComponent(freq);$('#'+prefix+'-error').innerHTML='';
   if(!compact){const start=$('#'+prefix+'-start').value;if(start&&Number.isFinite(Date.parse(start)))$('#schedule').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Payment</th><th>Estimated date</th><th>Amount</th></tr></thead><tbody>${schedule(amount,calcWeeks,freq,start).map((r,i)=>`<tr><td>${i+1}</td><td>${dateLabel(r.date)}</td><td>${money(r.amount/100)}</td></tr>`).join('')}</tbody></table></div>`;else $('#schedule').innerHTML='<p class="notice">Choose a date to see your estimated schedule.</p>';}
  }catch(err){$('#'+prefix+'-error').innerHTML=`<p class="error">${e(err.message)}</p>`;$('#'+prefix+'-result').innerHTML='';if(!compact)$('#schedule').innerHTML='';}
 };
 $$('[data-week]',box).forEach(b=>b.addEventListener('click',()=>{calcWeeks=Number(b.dataset.week);$$('[data-week]',box).forEach(btn=>{btn.classList.toggle('active',btn===b);btn.setAttribute('aria-pressed',String(btn===b));});update();}));
 $$('input,select',box).forEach(input=>input.addEventListener('input',update));update();
}
function lending(){return `<section class="hero dark"><div class="wrap"><div class="hero-grid"><div class="hero-copy"><div class="eyebrow">Avesta Lending</div><h1>Short-term finance.<br><em>Clearly explained.</em></h1><p>For the school fee, the next stock order, or the unexpected expense. Borrow for 1 to 4 weeks, with the cost and repayment dates stated before you commit.</p><div class="actions"><a class="button" href="/apply">Apply for a loan</a><a class="link" href="/how-it-works">How it works</a></div><p class="hero-note"><span></span> Cash, bank transfer or mobile money.</p></div>${quoteControls('quick',true)}</div><div class="trust-row"><div><strong>01–04</strong> Week terms</div><div><strong>15–30%</strong> Published flat interest</div><div><strong>Zambia</strong> Apply from wherever you are</div></div></div></section><section class="section"><div class="wrap"><div class="section-head"><div><div class="eyebrow">The full picture</div><h2>Four terms. No guesswork.</h2><p>Interest is applied once to the principal. Your agreement confirms the final repayment schedule.</p></div><a class="link" href="/calculator">Compare repayments</a></div><div class="rate-row">${Object.keys(rates).map(w=>`<a class="rate-card" href="/calculator?weeks=${w}"><strong>${w} ${w==='1'?'week':'weeks'}</strong><span class="rate">${rates[w]}%</span><span>Flat interest for the term</span></a>`).join('')}</div><p class="updated">Custom terms and any late charges must be agreed in writing. The calculator uses the published 1–4 week plans.</p></div></section><section class="section soft"><div class="wrap"><div class="section-head"><div><div class="eyebrow">A straightforward process</div><h2>From application to your next step.</h2></div></div><div class="steps-grid"><div><div class="step-number">01</div><h3>Tell us what you need</h3><p>Complete your application and provide the supporting documents.</p></div><div><div class="step-number">02</div><h3>We assess your application</h3><p>We review your circumstances and explain the terms before an agreement is signed.</p></div><div><div class="step-number">03</div><h3>Receive your funds</h3><p>After approval and signing, choose cash, mobile money or a bank transfer.</p></div></div><div class="actions"><a class="link" href="/how-it-works">Read the full process</a></div></div></section>`;}
function how(){return head('Avesta Lending','A clear path from<br><em>application to funds.</em>','Know what to prepare, what happens next, and what you are agreeing to.')+`<section class="section"><div class="wrap"><img class="how-image" src="/images/how-it-works.webp" alt="Illustration of the Avesta loan application process" width="1100" height="619" loading="lazy"><div class="steps-grid"><div><div class="step-number">01</div><h3>Complete your application</h3><p>Tell us about yourself, the loan you need, and your income. Choose your security arrangement and upload the supporting documents.</p></div><div><div class="step-number">02</div><h3>Assessment & agreement</h3><p>We review the application and contact you if anything needs clarification. Approval is subject to assessment. The amount, interest, dates and security are confirmed in your written agreement.</p></div><div><div class="step-number">03</div><h3>Disbursement & repayment</h3><p>After approval and signing, receive funds by cash, bank transfer, Airtel Money, MTN MoMo or Zamtel. Repay on the dates you agreed.</p></div></div></div></section><section class="section soft"><div class="wrap two-col"><div><div class="eyebrow">Have these ready</div><h2>A little preparation helps.</h2><p style="margin-top:18px">Clear documents make it easier to review your application.</p></div><div class="card"><h3>Application checklist</h3><ul><li>Your full name, NRC and contact details</li><li>Clear images of your NRC front and back</li><li>Your occupation, employer and monthly income</li><li>The amount, purpose and repayment plan</li><li>Details of collateral, salary check-off, an employer letter or guarantor, where applicable</li><li>Relevant supporting documents, such as a payslip</li></ul></div></div></section><section class="section"><div class="wrap narrow"><div class="eyebrow">Common questions</div><h2>Before you apply</h2><div style="margin-top:20px"><details><summary>How is interest calculated?</summary><p>Interest is simple and flat, applied once to your loan amount: 15% for 1 week, 20% for 2 weeks, 25% for 3 weeks and 30% for 4 weeks. For example, ZMW 1,000 over 2 weeks gives ZMW 200 interest and ZMW 1,200 total repayment.</p></details><details><summary>Can I apply outside Ndola?</summary><p>Yes. Avesta serves applicants across Zambia. Applications can be prepared online, and disbursement and repayment can use mobile money or bank transfer.</p></details><details><summary>Is approval guaranteed?</summary><p>No. Every application is assessed to determine whether a loan can be offered responsibly. Preparing or submitting an application does not mean a loan has been approved.</p></details><details><summary>What if I cannot repay on time?</summary><p>Contact Avesta as early as possible. Any late charges and revised repayment arrangement must follow your written agreement.</p></details><details><summary>Can I repay early?</summary><p>You may request an early settlement figure from the team. Interest is flat and applied once; your written agreement governs the amount due.</p></details></div><div class="actions"><a class="button secondary" href="/apply">Start an application</a><a class="link" href="/terms">Read the terms</a></div></div></section>`;}
function calculator(){const params=new URLSearchParams(location.search);if(rates[params.get('weeks')])calcWeeks=Number(params.get('weeks'));return head('Plan before you borrow','See the cost.<br><em>Choose with confidence.</em>','Estimate the full repayment amount and see a schedule that fits the published loan term.')+`<section class="section soft"><div class="wrap calculator-layout">${quoteControls('calc')}<div class="card schedule"><div class="eyebrow">Your estimated schedule</div><h2 style="font-size:1.7rem">Every payment, in view.</h2><p style="margin-top:15px">Dates below are based on your estimated disbursement date. Your signed agreement confirms the final dates.</p><div id="schedule"></div><div class="notice">Flat interest is applied once, not compounded. Instalments are rounded to the nearest ngwee and always add up to the total.</div><a class="link" href="/terms">Read the loan terms</a></div></div></section>`;}
function about(){return head('One company. Two ways to help.','Rooted in Ndola.<br><em>Here for Zambia.</em>','Avesta Enterprises brings accessible short-term finance and practical technology support to people, homes and businesses.')+`<section class="section"><div class="wrap about-block"><div><div class="eyebrow">Our story</div><h2>Keep it simple.<br>Do it properly.</h2><p style="margin-top:23px">Avesta was founded to bridge the gap between everyday Zambians and accessible finance. Our lending approach is built around treating every client with dignity, keeping the process clear, and explaining the costs before an agreement.</p><p>Avesta Consulting keeps the technology that businesses and homes depend on running. From a single laptop to a network and camera system, we explain what the job takes and what it costs before work starts.</p><p>Our office is on Thom Avenue in Kansenshi, Ndola. Lending and remote IT support reach across Zambia, with on-site IT work on the Copperbelt and in Lusaka, and elsewhere by arrangement.</p></div><blockquote class="large-quote" style="margin:0">Good support should be something you can understand — and something you can get hold of.<small>Our approach at Avesta</small></blockquote></div></section><section class="section soft"><div class="wrap"><div class="section-head"><div><div class="eyebrow">What guides us</div><h2>Clear work. Lasting trust.</h2></div></div><div class="card-grid"><article class="card">${icon('check')}<h3>Trust & integrity</h3><p>Clear terms, honest advice and costs explained before you commit.</p></article><article class="card">${icon('shield')}<h3>Responsible support</h3><p>Careful loan assessment and practical IT diagnosis that addresses the cause.</p></article><article class="card">${icon('pin')}<h3>Community focus</h3><p>Rooted in Ndola, supporting our neighbours and businesses across Zambia.</p></article></div></div></section><section class="section"><div class="wrap">${cta('What can we help with?','Explore lending or IT support, or speak with the team about what you need.','/contact','Talk to Avesta')}</div></section>`;}
function contact(){return head('We’re ready to listen','Let’s take<br><em>the next step.</em>','A loan question, a technology problem, or a visit to the office — choose the way that works for you.')+`<section class="section"><div class="wrap"><div class="contact-grid"><article class="card contact-card">${icon('phone')}<h3>Call or WhatsApp</h3><p><a href="tel:+260971013108">0971 013 108</a></p><p><a href="tel:+260769974200">0769 974 200</a></p><div class="actions"><a class="link" href="https://wa.me/260971013108" target="_blank" rel="noopener noreferrer">Open WhatsApp</a></div></article><article class="card contact-card">${icon('mail')}<h3>Email the team</h3><p>Tell us what you need and how we can reach you.</p><a href="mailto:info@avesta.solutions">info@avesta.solutions</a></article><article class="card contact-card">${icon('clock')}<h3>Office hours</h3><p>Monday–Saturday<br><strong>08:00–17:00</strong></p><p>Closed on Sundays.</p></article></div><div class="contact-office"><div class="office-address"><div class="eyebrow">Visit our head office</div><h3>Kansenshi, Ndola</h3><p>House No. 3, Thom Avenue<br>Kansenshi, Ndola, Zambia</p><div class="actions"><a class="button white" href="https://www.google.com/maps/search/?api=1&query=Thom+Avenue+Kansenshi+Ndola+Zambia" target="_blank" rel="noopener noreferrer">Open map & directions</a><a class="button" href="https://wa.me/260971013108?text=Hello%2C%20please%20send%20me%20directions%20to%20your%20office." target="_blank" rel="noopener noreferrer">Ask for directions</a></div></div><div class="card"><div class="eyebrow">Where we work</div><h3>Support across Zambia</h3><p style="margin-top:18px"><strong>Lending:</strong> Applications, mobile-money disbursement and bank transfers are available across Zambia.</p><p style="margin-top:15px"><strong>IT services:</strong> Remote websites, databases, data work, cybersecurity, training and advice reach anywhere. On-site repairs, networks and CCTV cover the Copperbelt and Lusaka, with other areas by arrangement.</p></div></div></div></section>`;}
const serviceCategory=i=>[0,1,3].includes(i)?'Repairs':[2,8,9].includes(i)?'Networks & security':'Digital & data';
function it(){return `<section class="hero"><div class="wrap"><div class="hero-grid"><div class="hero-copy"><div class="eyebrow" style="color:var(--blue)">Avesta Consulting</div><h1>Less downtime.<br><em>More doing.</em></h1><p>Practical IT services for businesses and homes. We explain the problem, the work and the cost before we start.</p><div class="actions"><a class="button blue" href="#enquiry" data-scroll="enquiry">Request IT support</a><a class="link" href="#help" data-scroll="help">Try the help guide</a></div><p class="hero-note"><span></span> Remote support across Zambia. On-site by arrangement.</p></div><div class="card"><div class="service-number">11</div><h2 style="margin-top:12px;font-family:Georgia,serif;font-weight:400;font-size:2.2rem">The technology you use.<br>The support you need.</h2><p style="margin-top:20px">Computers and software. Networks and Wi-Fi. Printers and CCTV. Websites, data, security and training.</p><div class="notice blue">From a single laptop to the systems your whole team depends on.</div><a class="link" href="tel:+260769974200">Call 0769 974 200</a></div></div></div></section><section class="section" id="services"><div class="wrap"><div class="section-head"><div><div class="eyebrow">What we do</div><h2>Find the right support.</h2></div><p>Explore all 11 services, or narrow the list to the work you need.</p></div><div class="service-search"><label class="field" for="service-search"><span class="sr-only">Search IT services</span><input id="service-search" type="search" placeholder="Search services, e.g. Wi-Fi or backup"></label><div class="filter-tabs" role="group" aria-label="Service categories">${['All','Repairs','Networks & security','Digital & data'].map(s=>`<button data-filter="${s}" type="button" class="${s===filter?'active':''}" aria-pressed="${s===filter}">${s}</button>`).join('')}</div></div><p class="updated" id="service-count" aria-live="polite" style="margin-bottom:18px"></p><div class="card-grid" id="service-grid"></div></div></section><section class="section soft" id="help"><div class="wrap assistant-layout"><div><div class="eyebrow">IT help desk</div><h2>Start with a<br>safe first step.</h2><p style="margin-top:20px">Describe what’s happening, or choose a common problem. Use the quick guide below, or open the assistant for follow-up questions and source links.</p><div class="chips">${[['printer','Printer offline'],['wifi','No internet'],['slow','Slow computer'],['virus','Suspicious activity'],['backup','Backups']].map(([v,t])=>`<button type="button" data-help="${v}">${t}</button>`).join('')}</div><p class="updated" style="margin-top:22px">An automated guide, not a technician. It cannot inspect your device. Stop and contact us if there is a risk to your data or equipment.</p></div><div class="card"><button class="button outline small" type="button" data-open-assistant>Open Avesta assistant</button><form id="help-form" style="margin-top:16px"><div class="input-row"><label class="field" for="help-question">What is happening?<input id="help-question" maxlength="300" placeholder="e.g. my printer says offline" required></label><button class="button secondary" type="submit">Ask</button></div></form><div class="help-result" id="help-result" aria-live="polite"><p>Choose a problem or describe it above to see relevant advice.</p></div></div></div></section><section class="section" id="enquiry"><div class="wrap two-col"><div><div class="eyebrow">Request support</div><h2>Tell us what<br>needs sorting.</h2><p style="margin-top:20px">Give us the service, your location and a short description. You can review the message before sending it through WhatsApp or email.</p><p style="margin-top:16px">Call <a class="link" href="tel:+260769974200">0769 974 200</a> for urgent support.</p></div><div class="card"><form id="enquiry-form"><div class="form-grid"><label class="field" for="it-name">Your name<input id="it-name" autocomplete="name" required maxlength="100"></label><label class="field" for="it-phone">Phone number<input id="it-phone" type="tel" autocomplete="tel" required></label><label class="field full" for="it-service">Service<select id="it-service">${services.map(s=>`<option>${e(s.name)}</option>`).join('')}</select></label><label class="field full" for="it-location">Town / location<input id="it-location" placeholder="e.g. Ndola, Kansenshi" required maxlength="200"></label><label class="field full" for="it-details">What do you need help with?<textarea id="it-details" required maxlength="2000"></textarea></label></div><div class="actions"><button type="submit" class="button blue">Prepare enquiry</button></div><p class="updated">Nothing is sent until you choose to send your prepared message.</p></form><div id="enquiry-result"></div></div></div></section>`;}
function bindIT(){
 const display=()=>{const search=$('#service-search').value.toLowerCase().trim();const found=services.map((s,i)=>({...s,i})).filter(s=>(filter==='All'||serviceCategory(s.i)===filter)&&(!search||(s.name+' '+s.description).toLowerCase().includes(search)));$('#service-count').textContent=found.length+' of '+services.length+' services';$('#service-grid').innerHTML=found.length?found.map(s=>`<article class="card service-card"><span class="service-number">${String(s.i+1).padStart(2,'0')}</span><h3>${e(s.name)}</h3><p>${e(s.description)}</p><button class="record-button link" type="button" data-enquire="${s.i}">Enquire about this service</button></article>`).join(''):'<div class="empty full"><h3>No services found</h3><p>Try a different keyword or choose All.</p></div>';$$('[data-enquire]').forEach(b=>b.addEventListener('click',()=>{$('#it-service').value=services[Number(b.dataset.enquire)].name;$('#enquiry').scrollIntoView({behavior:'smooth'});$('#it-name').focus({preventScroll:true});}));};
 $('#service-search').addEventListener('input',display);$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});display();}));display();
 $$('[data-scroll]').forEach(b=>b.addEventListener('click',ev=>{ev.preventDefault();document.getElementById(b.dataset.scroll).scrollIntoView({behavior:'smooth'});}));
 const answer=(query)=>{
  const q=query.toLowerCase().trim();let best=null,score=0;
  help.forEach(k=>{let n=(k.weight||[]).reduce((v,w)=>v+(q.includes(w.toLowerCase())?w.length:0),0);if(n>score){score=n;best=k;}});
  $('#help-result').innerHTML=best?`<h3>${e(best.title)}</h3><p>${e(best.answer)}</p><ol>${best.steps.map(s=>`<li>${e(s)}</li>`).join('')}</ol>${(best.sources||[]).length?`<p class="updated">Reference: ${(best.sources||[]).map(s=>`<a class="link" href="${e(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.title)}</a>`).join(' · ')}</p>`:''}${best.warn?`<div class="notice">${e(best.warn)}</div>`:''}<div class="notice blue">${e(best.call)}</div><a class="link" href="tel:+260769974200">Speak to Avesta</a>`:`<h3>Let’s get more detail.</h3><p>Try describing the device and what happens, such as “printer offline” or “laptop has no power”. For a diagnosis or a price, speak with the team.</p><div class="actions"><a class="button blue" href="https://wa.me/260769974200?text=${encodeURIComponent('Hello Avesta, I need IT help: '+query)}" target="_blank" rel="noopener noreferrer">Open WhatsApp</a></div>`;
 };
 $('#help-form').addEventListener('submit',ev=>{ev.preventDefault();answer($('#help-question').value);});$$('[data-help]').forEach(b=>b.addEventListener('click',()=>{$('#help-question').value=b.dataset.help;answer(b.dataset.help);}));
 $('#enquiry-form').addEventListener('submit',ev=>{ev.preventDefault();const message='Hello Avesta Consulting,\n\nName: '+$('#it-name').value+'\nPhone: '+$('#it-phone').value+'\nService: '+$('#it-service').value+'\nLocation: '+$('#it-location').value+'\n\n'+$('#it-details').value;$('#enquiry-result').innerHTML=`<div class="success"><h3>Your enquiry is ready</h3><p style="white-space:pre-wrap;margin-top:15px">${e(message)}</p><div class="actions"><a class="button blue" href="https://wa.me/260769974200?text=${encodeURIComponent(message)}" target="_blank" rel="noopener noreferrer">Send via WhatsApp</a><a class="button outline" href="mailto:info@avesta.solutions?subject=${encodeURIComponent('IT service enquiry')}&body=${encodeURIComponent(message)}">Send via email</a></div></div>`;});
 if(location.hash)requestAnimationFrame(()=>document.getElementById(decodeURIComponent(location.hash.slice(1)))?.scrollIntoView());
}
function currency(){return head('A useful estimate','Currency, without<br><em>the guesswork.</em>','Convert amounts using a dated indicative rate, or enter an agreed rate manually.')+`<section class="section soft"><div class="wrap calculator-layout"><div class="card"><form id="fx-form"><label class="field" for="fx-amount">Amount<input id="fx-amount" type="number" inputmode="decimal" value="1000" min="0" max="1000000000" step="0.01" required></label><div class="two-col"><label class="field" for="fx-from">From<select id="fx-from">${['ZMW','USD','EUR','GBP','ZAR','BWP'].map(c=>`<option>${c}</option>`).join('')}</select></label><label class="field" for="fx-to">To<select id="fx-to">${['USD','ZMW','EUR','GBP','ZAR','BWP'].map(c=>`<option>${c}</option>`).join('')}</select></label></div><button class="button outline small" id="fx-swap" type="button">Swap currencies</button><label class="field" for="fx-mode" style="margin-top:24px">Rate source<select id="fx-mode"><option value="indicative">Indicative market rate</option><option value="manual">Enter an agreed rate</option></select></label><label class="field" for="fx-rate" id="fx-manual" hidden>Rate: 1 unit of the source currency equals<input id="fx-rate" type="number" inputmode="decimal" step="0.000001" min="0.000001" placeholder="Enter target currency amount"><small>Enter the rate you agreed with the provider.</small></label><button class="button secondary" type="submit">Convert amount</button></form><p class="updated" id="fx-source">Loading indicative rates…</p></div><div class="card"><div class="eyebrow">Conversion estimate</div><div id="fx-result" aria-live="polite"><p>Choose your currencies and convert an amount.</p></div><div class="notice">These are indicative estimates, not Bank of Zambia buy/sell quotes or a promise of a transaction rate. Fees and provider margins may change the amount you receive.</div><p>For a lending estimate in kwacha, use the <a class="link" href="/calculator">loan calculator</a>.</p></div></div></section>`;}
async function request(path,options={}){
 const response=await fetch(path,options);let data;try{data=await response.json();}catch{throw new Error('The service could not be reached. Please try again.');}
 if(!response.ok)throw new Error(data.error||'The service is temporarily unavailable.');return data;
}
async function bindFX(){
 let data=null;const mode=$('#fx-mode'),manual=$('#fx-manual'),source=$('#fx-source');
 mode.addEventListener('change',()=>{manual.hidden=mode.value!=='manual';$('#fx-rate').required=mode.value==='manual';});
 $('#fx-swap').addEventListener('click',()=>{const v=$('#fx-from').value;$('#fx-from').value=$('#fx-to').value;$('#fx-to').value=v;const r=Number($('#fx-rate').value);if(r>0)$('#fx-rate').value=(1/r).toFixed(6);});
 $('#fx-form').addEventListener('submit',ev=>{ev.preventDefault();try{const amount=Number($('#fx-amount').value),from=$('#fx-from').value,to=$('#fx-to').value;if(!Number.isFinite(amount)||amount<0)throw new Error('Enter a valid amount.');let rate=from===to?1:mode.value==='manual'?Number($('#fx-rate').value):data?.rates[to]/data?.rates[from];if(!Number.isFinite(rate)||rate<=0)throw new Error('Enter a valid rate manually, or try loading indicative rates again.');$('#fx-result').innerHTML=`<p>${amount.toLocaleString('en-ZM',{maximumFractionDigits:2})} ${from}</p><div class="quote-total"><strong>${(amount*rate).toLocaleString('en-ZM',{minimumFractionDigits:2,maximumFractionDigits:2})} ${to}</strong></div><p class="updated">1 ${from} = ${rate.toFixed(6)} ${to}</p><p class="updated">${mode.value==='manual'?'Manually entered rate':e('Indicative · '+(data?.source||'')+' · '+(data?dateLabel(data.asOf):''))}</p>`;}catch(err){$('#fx-result').innerHTML=`<p class="error">${e(err.message)}</p>`;}});
 try{data=await request('/api/rates');if(route!=='/currency')return;source.textContent='Indicative · '+data.source+' · updated '+dateLabel(data.asOf);$('#fx-form').requestSubmit();}catch(err){if(route!=='/currency')return;source.textContent=err.message;mode.value='manual';mode.dispatchEvent(new Event('change'));}
}
function dateLabel(value){return new Date(String(value).length===10?value+'T12:00:00Z':value).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Africa/Lusaka'});}
function field(name,label,type='text',extra=''){return `<label class="field" for="a-${name}">${label}<input id="a-${name}" name="${name}" type="${type}" value="${e(appData[name]||'')}" ${extra}></label>`;}
function select(name,label,options){return `<label class="field" for="a-${name}">${label}<select id="a-${name}" name="${name}" required>${options.map(v=>`<option value="${e(v)}" ${appData[name]===v?'selected':''}>${name==='weeks'?e(v+' '+(v==='1'?'week':'weeks')+' · '+rates[v]+'% flat'):e(v)}</option>`).join('')}</select></label>`;}
function upload(name,label,required=false){return `<label class="field upload-field" for="a-${name}">${label}${required?' *':''}<input id="a-${name}" name="${name}" type="file" accept="application/pdf,image/jpeg,image/png,image/webp" data-file="${name}"><small>${appFiles[name]?e(appFiles[name].name):'PDF, JPG, PNG or WebP · up to 5 MB'}</small></label>`;}
const steps=['Borrower','Loan','Repayment','Documents','Review'];
function apply(){const p=new URLSearchParams(location.search);if(!Object.keys(appData).length){appData={amount:p.get('amount')||'1000',weeks:p.get('weeks')||'2',frequency:p.get('frequency')||'Lump sum',security:'None',method:'Cash',repaymentMethod:'Cash'};}return head('Avesta Lending','Your application.<br><em>One step at a time.</em>','Complete the details, attach your documents, then review before submitting. An application is not an approval or a signed loan agreement.')+`<section class="section soft"><div class="wrap narrow"><div class="notice blue no-print">Private review workspace. Applications saved here are accessible only through your signed-in account. Existing Avesta customer records have not been imported.</div><div class="form-shell" id="application-shell">${appData.submitted?applicationSuccess():wizard()}</div></div></section>`;}
function collectStep(){
 const form=$('#application-form');if(!form)return;
 $$('[name]',form).forEach(el=>{if(el.type==='file'){if(el.files[0])appFiles[el.dataset.file]=el.files[0];}else if(el.type==='checkbox')appData[el.name]=el.checked;else appData[el.name]=el.value;});
}
function wizard(){
 let content='';
 if(appStep===0)content=`<h2>First, a little about you.</h2><p class="intro">Your identity, contact details and income help us assess your application.</p><div class="form-grid">${field('name','Full name','text','required autocomplete="name" maxlength="100"')}${field('nrc','NRC number','text','required placeholder="123456/78/9" pattern="[0-9]{6}/[0-9]{2}/[0-9]"')}${field('dob','Date of birth','date','required max="'+today()+'"')}${field('phone','Phone number','tel','required autocomplete="tel" placeholder="0971 013 108"')}${field('email','Email (optional)','email','autocomplete="email"')}${field('address','Residential address','text','required autocomplete="street-address" maxlength="1000"')}${field('occupation','Occupation','text','required maxlength="150"')}${field('employer','Employer / business (optional)','text','maxlength="150"')}${field('income','Monthly income (ZMW)','number','required min="0" step="0.01"')}${select('security','Security arrangement',['None','Collateral','Salary check-off','Employer letter','Guarantor'])}<div class="full" id="security-details" ${appData.security==='None'?'hidden':''}><label class="field" for="a-securityDetails">Security details<textarea id="a-securityDetails" name="securityDetails" maxlength="2000" placeholder="Collateral item and estimated value, employer/payroll details, or guarantor name and contact.">${e(appData.securityDetails||'')}</textarea></label></div></div>`;
 if(appStep===1)content=`<h2>Choose your loan.</h2><p class="intro">Published terms run from 1 to 4 weeks. The final offer is subject to assessment.</p><div class="form-grid">${field('amount','Loan amount (ZMW)','number','required min="1" max="1000000" step="0.01"')}${select('weeks','Loan term',['1','2','3','4'])}<label class="field full" for="a-purpose">Purpose of loan<textarea id="a-purpose" name="purpose" required maxlength="2000">${e(appData.purpose||'')}</textarea></label>${select('method','Preferred disbursement',['Cash','Airtel Money','MTN MoMo','Zamtel','ZANACO','FNB','Stanbic','Other bank'])}<div class="full" id="account-details" ${appData.method==='Cash'?'hidden':''}>${field('account','Account name and mobile / bank account','text','maxlength="200"')}</div></div><div id="app-quote" class="notice"></div>`;
 if(appStep===2)content=`<h2>Plan your repayments.</h2><p class="intro">Choose a frequency and payment method. Dates are confirmed in your written agreement.</p><div class="form-grid">${select('frequency','Repayment frequency',['Weekly','Bi-weekly','Monthly','Lump sum'])}${select('repaymentMethod','Repayment method',['Cash','Airtel Money','MTN MoMo','Zamtel','Bank transfer'])}</div><div id="app-quote" class="notice"></div><p class="updated">Monthly or lump-sum repayment falls at the end of the selected 1–4 week term. Bi-weekly plans include a final payment at term end if needed.</p>`;
 if(appStep===3)content=`<h2>Add your documents.</h2><p class="intro">Upload clear, readable copies. Fields marked * are required. The combined upload limit is 20 MB.</p><div class="form-grid">${upload('nrcFront','NRC front',true)}${upload('nrcBack','NRC back',true)}${appData.security==='Collateral'?upload('collateral','Collateral photograph',true):''}${appData.security==='Employer letter'?upload('employerLetter','Employer confirmation letter',true):''}${upload('payslip','Payslip / proof of income') }${upload('bankStatement','Bank statement') }${upload('utility','Utility bill / proof of address') }${appData.security==='Guarantor'?upload('guarantor','Guarantor NRC'):''}</div><div class="notice">Documents stay in this private workspace. Do not upload anyone’s document without their permission.</div>`;
 if(appStep===4)content=`<h2>Check every detail.</h2><p class="intro">You can go back to change anything before submitting.</p>${reviewSummary()}<div class="notice">This is an application, not a loan offer or a signed lending contract. Approval, final terms and signatures are handled with Avesta after assessment.</div><label class="check"><input type="checkbox" name="declaration" ${appData.declaration?'checked':''} required> <span>I confirm that the information is accurate and complete.</span></label><label class="check"><input type="checkbox" name="consent" ${appData.consent?'checked':''} required> <span>I have read the <a class="link" href="/privacy" target="_blank" rel="noopener">privacy information</a> and agree to the information being used to assess this application.</span></label>${field('signature','Type your full name to acknowledge the application','text','required maxlength="100"')}<p class="updated">This acknowledgement does not replace a signed loan agreement.</p>`;
 return `<div class="wizard-progress" aria-label="Application progress">${steps.map((s,i)=>`<span class="${i===appStep?'active':i<appStep?'complete':''}" ${i===appStep?'aria-current="step"':''}><b>${i+1}</b>${s}</span>`).join('')}</div><div class="wizard-body"><form id="application-form">${content}<div id="application-error" role="alert"></div><div class="wizard-actions"><button type="button" id="app-back" class="button outline" ${appStep===0?'disabled':''}>Back</button><span class="step-label">Step ${appStep+1} of 5</span><button type="submit" id="app-next" class="button secondary">${appStep===4?'Submit application':'Continue'}</button></div></form></div>`;
}
function reviewSummary(){
 let q;try{q=quote(appData.amount,appData.weeks,appData.frequency);}catch{return '<p class="error">Check the loan amount and term.</p>';}
 const details=[['Applicant',appData.name],['NRC',appData.nrc],['Phone',appData.phone],['Address',appData.address],['Loan amount',money(q.principal/100)],['Term & interest',appData.weeks+' weeks · '+q.rate+'% flat'],['Total to repay',money(q.total/100)],['Repayment',appData.frequency],['Disbursement',appData.method],['Purpose',appData.purpose],['Security',appData.security],['Documents',Object.keys(appFiles).map(k=>appFiles[k].name).join(', ')]];
 return `<div class="review-list">${details.map(([key,value])=>`<div><span>${key}</span><strong>${e(value||'—')}</strong></div>`).join('')}</div>`;
}
function applicationSuccess(){return `<div class="wizard-body"><div class="success"><div class="eyebrow">Saved in your private workspace</div><h2>Application submitted.</h2><p style="margin-top:15px">Your reference is <strong>${e(appData.submitted)}</strong>. The application is pending review. This does not mean the loan has been approved.</p><div class="actions no-print"><a class="button secondary" href="/portal">View in portal</a><button class="button outline" id="print-application" type="button">Print / save PDF</button></div></div><div style="margin-top:28px">${reviewSummary()}</div><div class="actions no-print"><button class="record-button" id="new-application" type="button">Start a new application</button></div></div>`;}
function bindApplication(){
 if(appData.submitted){$('#print-application').onclick=()=>window.print();$('#new-application').onclick=()=>{appData={};appFiles={};appStep=0;render();};return;}
 const form=$('#application-form');
 $$('input:not([type=file]),select,textarea',form).forEach(el=>el.addEventListener('input',()=>{collectStep();if(el.name==='security'){$('#security-details').hidden=el.value==='None';$('#a-securityDetails').required=el.value!=='None';}if(el.name==='method'){$('#account-details').hidden=el.value==='Cash';$('#a-account').required=el.value!=='Cash';}updateAppQuote();}));
 if($('#a-securityDetails'))$('#a-securityDetails').required=appData.security!=='None';
 if($('#a-account'))$('#a-account').required=appData.method!=='Cash';
 $$('[data-file]').forEach(input=>input.addEventListener('change',()=>{const file=input.files[0];if(file){if(file.size>5*1024*1024){toast('Choose a document up to 5 MB.');input.value='';return;}appFiles[input.dataset.file]=file;input.nextElementSibling.textContent=file.name;}}));
 $('#app-back').onclick=()=>{collectStep();if(appStep>0)appStep--;$('#application-shell').innerHTML=wizard();bindApplication();};
 updateAppQuote();
 form.addEventListener('submit',async ev=>{ev.preventDefault();if(appSaving)return;collectStep();try{
  if(appStep===0){if(!/^(?:\+?260|0)[0-9]{9}$/.test((appData.phone||'').replace(/[\s-]/g,'')))throw new Error('Enter a valid Zambian phone number.');const cutoff=new Date();cutoff.setUTCFullYear(cutoff.getUTCFullYear()-18);if(appData.dob>cutoff.toISOString().slice(0,10))throw new Error('Applicant must be at least 18 years old.');}
  if(appStep===1||appStep===2)quote(appData.amount,appData.weeks,appData.frequency);
  if(appStep===3){if(!appFiles.nrcFront||!appFiles.nrcBack)throw new Error('Please add the front and back of your NRC.');if(appData.security==='Collateral'&&!appFiles.collateral)throw new Error('Please add a collateral photo.');if(appData.security==='Employer letter'&&!appFiles.employerLetter)throw new Error('Please add the employer letter.');}
  if(appStep<4){appStep++;$('#application-shell').innerHTML=wizard();bindApplication();$('.wizard-body').scrollIntoView({behavior:'smooth',block:'start'});return;}
  appSaving=true;$('#app-next').disabled=true;$('#app-back').disabled=true;$('#app-next').textContent='Saving application…';
  const fd=new FormData();fd.set('payload',JSON.stringify(appData));for(const [key,file]of Object.entries(appFiles))fd.set(key,file);
  const result=await request('/api/applications',{method:'POST',body:fd});appSaving=false;appData.submitted=result.id;$('#application-shell').innerHTML=applicationSuccess();bindApplication();
 }catch(err){appSaving=false;$('#app-back').disabled=appStep===0;$('#application-error').innerHTML=`<p class="error">${e(err.message)}</p>`;if($('#app-next')){$('#app-next').disabled=false;$('#app-next').textContent=appStep===4?'Submit application':'Continue';}}});
}
function updateAppQuote(){if(!$('#app-quote'))return;try{const q=quote(appData.amount,appData.weeks,appData.frequency);$('#app-quote').innerHTML=`<strong>${money(q.total/100)} total repayment.</strong> ${money(q.principal/100)} principal + ${money(q.interest/100)} interest (${q.rate}% flat). ${q.count} ${q.count===1?'payment':'payments'}.`;}catch(err){$('#app-quote').textContent=err.message;}}
const policyTexts={
 '/privacy':`<h2>Assistant conversations</h2><p>Saved guidance is processed by this site. If you choose AI and online sources, your question and up to six recent messages are sent to OpenAI and may be used for web searches. The site keeps chat history only in page memory until you clear it or close the page. OpenAI’s own data handling applies to API requests. Do not share passwords, NRC numbers, account details or documents in chat. The assistant cannot read your loan records. For usage limits, the site records a signed-in user identifier, hourly time bucket and request count, with old counters removed on subsequent AI requests.</p><p>Avesta uses personal information to assess loan applications, administer repayments and provide IT services. This private review site stores only records you create here; original customer records have not been imported.</p><h2>Information collected</h2><ul><li>Identity: full name, NRC number, date of birth and NRC images.</li><li>Contact: phone, optional email and residential address.</li><li>Financial: occupation, employer, income, loan request, repayment preferences and security details.</li><li>Supporting documents that you choose to upload.</li><li>Application status, payments and activity records.</li></ul><h2>Use and access</h2><p>Information is used to assess the application, contact the applicant and administer the loan. This deployment is private and uses ChatGPT sign-in. Application records and documents are restricted to the signed-in account that created them. Documents are downloaded through authenticated endpoints, rather than public file links.</p><h2>Where information is stored</h2><p>This review version uses the Sites hosting platform and its connected data storage. It does not make a claim that the servers are located in Zambia. The production data handling and storage arrangements must be confirmed before this version is opened to customers.</p><h2>Your choices</h2><p>You can review information before submission. Do not upload another person’s information without permission. Contact Avesta to request a copy, correction or removal of information where appropriate, or to raise a privacy concern.</p><h2>Sign-in and preferences</h2><p>ChatGPT handles sign-in for this private site. The application does not store your password. Form progress remains in page memory until the page is closed; it is not stored as a customer record until you submit it.</p>`,
 '/terms':`<p>These pages explain Avesta’s lending process. The written loan agreement, once agreed and signed with Avesta, sets the binding loan terms. Submitting an application here is not a loan approval or acceptance of a lending contract.</p><h2>Published loan plans</h2><div class="table-wrap"><table><thead><tr><th>Term</th><th>Flat interest</th><th>Example on ZMW 1,000</th></tr></thead><tbody>${Object.keys(rates).map(w=>`<tr><td>${w} ${w==='1'?'week':'weeks'}</td><td>${rates[w]}%</td><td>${money(quote(1000,w).total/100)}</td></tr>`).join('')}</tbody></table></div><p>Interest is simple and flat, applied once to the principal. The calculator does not compound interest. Your agreement confirms the amount, interest, total repayment, dates and security.</p><h2>Repayment responsibilities</h2><ul><li>Give accurate and complete information.</li><li>Repay the agreed amount on the agreed dates.</li><li>Tell Avesta promptly if your circumstances change or you expect difficulty paying.</li></ul><h2>Security and collateral</h2><p>Collateral, salary check-off, employer-letter and guarantor arrangements are subject to assessment and the written agreement. Collateral is returned once the loan is settled in full, as set out in that agreement.</p><h2>Late payment and early settlement</h2><p>Late charges and any revised schedule are governed by the written agreement. Contact Avesta early if you are struggling. You may request an early settlement figure from the team.</p><h2>Application and agreement</h2><p>Approval is subject to assessment. You receive a copy of your signed agreement. The typed acknowledgement in this online application confirms the accuracy of the request; it does not replace the lending contract or guarantee disbursement.</p><h2>IT services</h2><p>Avesta Consulting explains the work and cost before starting. On-site availability outside the Copperbelt and Lusaka is by arrangement. An enquiry is not a confirmed booking.</p><h2>Private website access</h2><p>This review version is for private use. Keep your sign-in secure. Currency conversions are indicative estimates, unless you enter an agreed rate yourself; they are not a promise of a transaction rate.</p><h2>Questions</h2><p>For the final terms of a proposed loan or IT job, speak directly with Avesta. You can also use our complaints process below.</p>`,
 '/complaints':`<p>If something has gone wrong, we want to hear about it. Give us your name, application or enquiry reference if you have one, and a description of what happened.</p><h2>1. Tell us</h2><p>Contact us by phone, WhatsApp, email or in person. You do not need to put your complaint in writing, though it helps.</p><h2>2. Acknowledgement</h2><p>Avesta’s stated process is to acknowledge receipt within <strong>two working days</strong> and tell you who is handling the complaint.</p><h2>3. Investigation</h2><p>The team reviews what happened and aims to provide a written answer within <strong>fourteen working days</strong>. If more time is needed, the team explains why and when to expect an answer.</p><h2>4. Management review</h2><p>If you disagree with the answer, ask for management review and explain why. The stated review period is a further fourteen working days.</p><h2>5. Further action</h2><p>This process does not limit your legal rights. You may seek independent advice or contact the relevant regulator about an unresolved matter.</p><div class="actions"><a class="button secondary" href="mailto:info@avesta.solutions?subject=Complaint">Email a complaint</a><a class="button outline" href="tel:+260971013108">Call the team</a></div>`
};
function policy(){return head('Avesta Enterprises',pageTitles[route],'Clear information to help you understand the service and your choices.')+`<section class="section"><div class="wrap policies"><nav class="policy-nav" aria-label="Policy pages">${[['/privacy','Privacy'],['/terms','Terms'],['/complaints','Complaints']].map(([p,t])=>`<a href="${p}" class="${route===p?'active':''}" ${route===p?'aria-current="page"':''}>${t}</a>`).join('')}</nav>${policyTexts[route]}<div class="notice">Avesta Enterprises · House No. 3, Thom Avenue, Kansenshi, Ndola · <a class="link" href="mailto:info@avesta.solutions">info@avesta.solutions</a> · 0971 013 108 / 0769 974 200</div></div></section>`;}
function portal(){return head('Your private workspace','Applications, organised.<br><em>Repayments, in view.</em>','Review applications created in this site, track statuses, download documents and record repayments.')+`<section class="section soft"><div class="wrap"><div class="portal-head"><div><p id="portal-account" class="updated">Private, signed-in account</p><p class="updated">No original customer records have been imported.</p></div><div class="actions"><button class="button outline small" id="portal-refresh" type="button">Refresh</button><button class="button outline small" id="portal-export" type="button">Export records</button><a class="button secondary small" href="/apply">New application</a></div></div><div id="portal-message" role="alert"></div><div id="metrics"></div><div class="portal-controls"><label class="field" for="portal-search">Find an application<input id="portal-search" type="search" placeholder="Name, phone or reference"></label><label class="field" for="portal-status">Status<select id="portal-status"><option>All statuses</option>${['Pending','Under Review','Approved','Rejected','Disbursed','Repaid'].map(s=>`<option>${s}</option>`).join('')}</select></label><button class="button outline" id="portal-audit" type="button">View activity log</button></div><div class="card" style="padding:0;overflow:hidden"><div id="records"><div class="loading">Loading applications…</div></div></div></div></section>`;}
function renderRecords(){
 const book=loanBook(records);$('#metrics').innerHTML=`<div class="metrics"><div class="metric"><span>Applications</span><strong>${records.length}</strong><small>${records.filter(r=>r.status==='Pending').length} pending review</small></div><div class="metric"><span>Outstanding balance</span><strong>${money(book.balance/100)}</strong><small>${money(book.dueSoon/100)} due in 7 days</small></div><div class="metric"><span>Collected</span><strong>${money(book.collected/100)}</strong><small>${book.total?Math.round(book.collected/book.total*100):0}% of active loan totals</small></div><div class="metric"><span>Past term end</span><strong>${money(book.overdue/100)}</strong><small>${book.overdueCount} loans outstanding</small></div></div>`;
 const search=$('#portal-search').value.toLowerCase(),status=$('#portal-status').value;
 const filtered=records.filter(r=>(status==='All statuses'||r.status===status)&&(!search||(r.name+' '+r.phone+' '+r.id).toLowerCase().includes(search)));
 $('#records').innerHTML=filtered.length?`<div class="table-wrap"><table><thead><tr><th>Applicant</th><th>Reference</th><th>Loan</th><th>Status</th><th>Balance</th><th></th></tr></thead><tbody>${filtered.map(r=>`<tr><td><strong>${e(r.name)}</strong><p class="updated">${e(r.phone)}</p></td><td>${e(r.id)}<p class="updated">${dateLabel(r.submitted)}</p></td><td>${money(r.amount/100)}<p class="updated">${r.weeks} weeks</p></td><td><span class="status ${r.status.toLowerCase()}">${e(r.status)}</span></td><td>${['Disbursed','Repaid'].includes(r.status)?money(Math.max(0,r.total-r.paid)/100):'—'}</td><td><button class="record-button" type="button" data-record="${e(r.id)}">View</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><h3>${records.length?'No matching applications':'Your workspace is ready.'}</h3><p>${records.length?'Try another search or status.':'Applications you submit on this site will appear here. No sample or customer data has been added.'}</p>${records.length?'':'<a class="button secondary" href="/apply">Start an application</a>'}</div>`;
 $$('[data-record]').forEach(b=>b.addEventListener('click',()=>openRecord(b.dataset.record)));
}
async function loadRecords(){try{const data=await request('/api/applications');if(route!=='/portal')return;records=data.records;$('#portal-message').innerHTML='';renderRecords();}catch(err){if(route!=='/portal')return;$('#portal-message').innerHTML=`<p class="error">${e(err.message)}</p>`;$('#records').innerHTML='<div class="empty"><h3>Applications could not be loaded.</h3><p>Try Refresh. No records have been changed.</p></div>';}}
function bindPortal(){
 $('#portal-refresh').onclick=loadRecords;$('#portal-search').oninput=renderRecords;$('#portal-status').onchange=renderRecords;
 $('#portal-export').onclick=()=>{if(!records.length){toast('There are no records to export.');return;}const b=new Blob([JSON.stringify({exported:new Date().toISOString(),applications:records},null,2)],{type:'application/json'});const url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='Avesta-applications-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Application export downloaded. Documents and payment entries are managed separately.');};
 $('#portal-audit').onclick=async()=>{try{const a=await request('/api/audit');$('#dialog-content').innerHTML=`<div class="eyebrow">Workspace activity</div><h2>Activity log</h2><p class="updated">The latest 100 actions in your private account.</p><div class="audit-list">${a.events.length?a.events.map(event=>`<div class="payment-row"><div><strong>${e(event.action)}</strong><small>${e(event.reference)}</small></div><small>${new Date(event.time).toLocaleString('en-GB',{timeZone:'Africa/Lusaka'})}</small></div>`).join(''):'<p>No recorded activity yet.</p>'}</div>`;$('#dialog').showModal();}catch(err){toast(err.message);}};
 request('/api/me').then(d=>{if(route==='/portal')$('#portal-account').textContent=d.email?'Signed in as '+d.email:'Private signed-in account';}).catch(()=>{});loadRecords();
}
async function openRecord(id){
 currentRecord=records.find(r=>r.id===id);if(!currentRecord)return;const r=currentRecord,d=r.data;
 $('#dialog-content').innerHTML=`<div class="eyebrow">${e(r.id)}</div><h2>${e(r.name)}</h2><p class="updated">Submitted ${dateLabel(r.submitted)} · ${e(r.status)}</p><div class="review-list" style="margin-top:24px">${[['Phone',r.phone],['Email',r.email||'—'],['NRC',d.nrc],['Address',d.address],['Occupation',d.occupation],['Monthly income',money(d.income)],['Purpose',d.purpose],['Security',d.security],['Security details',d.securityDetails||'—'],['Account',d.account||'Cash'],['Amount',money(r.amount/100)],['Total repayment',money(r.total/100)],['Payment plan',d.frequency],['Disbursed',r.disbursed?dateLabel(r.disbursed):'Not disbursed']].map(([k,v])=>`<div><span>${k}</span><strong>${e(v)}</strong></div>`).join('')}</div><h3>Application status</h3><form id="status-form"><div class="two-col"><label class="field" for="record-status">Status<select id="record-status" ${r.status==='Repaid'?'disabled':''}>${['Pending','Under Review','Approved','Rejected','Disbursed',...(r.status==='Repaid'?['Repaid']:[])].map(s=>`<option ${r.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field" for="record-disbursed">Disbursement date<input id="record-disbursed" type="date" value="${r.disbursed||today()}" max="${today()}"></label></div><button class="button secondary small" type="submit" ${r.status==='Repaid'?'disabled':''}>Save status</button></form><div id="record-error" role="alert"></div><h3>Supporting documents</h3><div id="record-docs">Loading documents…</div><h3>Repayments</h3><p><strong>Outstanding: ${money(Math.max(0,r.total-r.paid)/100)}</strong> · Collected: ${money(r.paid/100)}</p><div id="record-payments">Loading repayments…</div>${r.status==='Disbursed'?`<form id="payment-form" style="margin-top:24px"><div class="form-grid"><label class="field" for="payment-amount">Payment amount (ZMW)<input id="payment-amount" type="number" step="0.01" min="0.01" max="${(r.total-r.paid)/100}" required></label><label class="field" for="payment-date">Payment date<input id="payment-date" type="date" value="${today()}" min="${r.disbursed}" max="${today()}" required></label><label class="field" for="payment-method">Method<select id="payment-method"><option>Cash</option><option>Mobile money</option><option>Bank transfer</option></select></label><label class="field" for="payment-note">Reference / note (optional)<input id="payment-note" maxlength="500"></label></div><button type="submit" class="button secondary small">Record payment</button></form>`:`<p class="updated">${r.status==='Repaid'?'This loan is settled.':'Record disbursement before adding payments.'}</p>`}`;
 if(!$('#dialog').open)$('#dialog').showModal();
 $('#status-form').onsubmit=async ev=>{ev.preventDefault();try{await request('/api/applications/'+r.id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({status:$('#record-status').value,disbursed:$('#record-disbursed').value})});await loadRecords();await openRecord(r.id);toast('Status saved.');}catch(err){$('#record-error').innerHTML=`<p class="error">${e(err.message)}</p>`;}};
 if($('#payment-form'))$('#payment-form').onsubmit=async ev=>{ev.preventDefault();const b=$('#payment-form button');b.disabled=true;try{await request('/api/applications/'+r.id+'/payments',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({amount:$('#payment-amount').value,date:$('#payment-date').value,method:$('#payment-method').value,note:$('#payment-note').value})});await loadRecords();await openRecord(r.id);toast('Payment recorded.');}catch(err){$('#record-error').innerHTML=`<p class="error">${e(err.message)}</p>`;b.disabled=false;}};
 try{const [docs,pays]=await Promise.all([request('/api/applications/'+r.id+'/documents'),request('/api/applications/'+r.id+'/payments')]);if(currentRecord?.id!==r.id)return;$('#record-docs').innerHTML=docs.documents.length?docs.documents.map(doc=>`<div class="payment-row"><a class="link" href="/api/documents/${e(doc.id)}" download>${e(doc.name)}</a><small>${Math.round(doc.size/1024)} KB</small></div>`).join(''):'<p>No documents.</p>';$('#record-payments').innerHTML=pays.payments.length?pays.payments.map(p=>`<div class="payment-row"><div><strong>${money(p.amount/100)}</strong><small>${dateLabel(p.date)} · ${e(p.method)} · ${e(p.note)}</small></div><button class="record-button danger" type="button" data-delete-payment="${e(p.id)}">Remove</button></div>`).join(''):'<p class="updated">No repayments recorded.</p>';$$('[data-delete-payment]').forEach(b=>b.onclick=async()=>{if(!confirm('Remove this payment? The balance will be recalculated and the change recorded in the activity log.'))return;try{await request('/api/payments/'+b.dataset.deletePayment,{method:'DELETE'});await loadRecords();await openRecord(r.id);toast('Payment removed.');}catch(err){toast(err.message);}});
 }catch(err){if(currentRecord?.id===r.id){$('#record-docs').innerHTML=`<p class="error">${e(err.message)}</p>`;$('#record-payments').innerHTML='';}}
}
function render(){
 shell();if($('#dialog').open)$('#dialog').close();
 const views={'/':home,'/lending':lending,'/how-it-works':how,'/calculator':calculator,'/about':about,'/contact':contact,'/it':it,'/currency':currency,'/apply':apply,'/portal':portal,'/privacy':policy,'/terms':policy,'/complaints':policy};
 main.innerHTML=views[route]?views[route]():head('Avesta Enterprises','Page not found.','Use the navigation to find lending, IT support or the contact details.')+'<section class="section"><div class="wrap"><a class="button secondary" href="/">Return home</a></div></section>';
 if(route==='/lending')bindQuote('quick',true);
 if(route==='/calculator')bindQuote('calc');
 if(route==='/it')bindIT();
 if(route==='/currency')bindFX();
 if(route==='/apply')bindApplication();
 if(route==='/portal')bindPortal();
}
async function start(){try{[services,help]=await Promise.all([request('/services.json'),request('/help.json')]);render();}catch(err){main.innerHTML=head('Avesta Enterprises','We couldn’t load the page.','Please reload or contact Avesta on 0971 013 108.')+`<section class="section"><div class="wrap"><p class="error">${e(err.message)}</p><button class="button secondary" id="reload-page">Reload</button></div></section>`;$('#reload-page').onclick=()=>location.reload();}}
start();
const modelContext=document.modelContext;
if(modelContext?.registerTool){
 const lifecycle=new AbortController();
 const register=(tool)=>{try{Promise.resolve(modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'configure_loan_estimate',title:'Estimate Avesta loan',description:'Open the calculator and configure an estimate using the published rates. Does not apply for or approve a loan.',inputSchema:{type:'object',properties:{amount:{type:'number',minimum:1},weeks:{type:'integer',minimum:1,maximum:4},frequency:{type:'string',enum:['Weekly','Bi-weekly','Monthly','Lump sum']}},required:['amount','weeks'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.amount!=='number'||!Number.isInteger(input.weeks))throw new Error('Enter a numeric amount and a whole-week term.');const q=quote(input.amount,input.weeks,input.frequency||'Lump sum');if(input.frequency&&!['Weekly','Bi-weekly','Monthly','Lump sum'].includes(input.frequency))throw new Error('Invalid repayment frequency.');calcWeeks=input.weeks;navigate('/calculator');$('#calc-amount').value=String(input.amount);$('#calc-frequency').value=input.frequency||'Lump sum';$('#calc-amount').dispatchEvent(new Event('input'));return {principal:q.principal/100,interest:q.interest/100,total:q.total/100,rate:q.rate};}});
 register({name:'start_loan_application',title:'Start a loan application',description:'Open the application form. Does not submit an application or enter a loan agreement.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(){navigate('/apply');return {page:'Loan application',submitted:false};}});
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
